CREATE TABLE `initiative` (
  `tagNumber` int NOT NULL,
  `initiativeName` varchar(200) DEFAULT NULL,
  `initiativeWebsite` varchar(400) DEFAULT NULL,
  `targetsWomen` varchar(30) DEFAULT NULL,
  `startYear` varchar(30) DEFAULT NULL,
  `endYear` varchar(30) DEFAULT NULL,
  `description` text,
  `mainProgrammingArea` varchar(200) DEFAULT NULL,
  `mainProgrammingActivity` varchar(300) DEFAULT NULL,
  `feeToAccess` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`tagNumber`),
  KEY `mainProgrammingArea` (`mainProgrammingArea`),
